import{_ as e}from"./chunks/formats.Bqa4Tjr1.js";import{_ as s,C as p,o as n,c as d,j as a,a as h,E as o,a2 as r}from"./chunks/framework.BefGvJmu.js";const C=JSON.parse('{"title":".pai 文档格式","description":"把文字、布局、原图和文档标识保存在一起，使用 .pai 保存，或导出可独立编辑的 .pai.html。","frontmatter":{"title":".pai 文档格式","description":"把文字、布局、原图和文档标识保存在一起，使用 .pai 保存，或导出可独立编辑的 .pai.html。"},"headers":[],"relativePath":"zh/format.md","filePath":"zh/format.md"}'),l={name:"zh/format.md"};function c(k,t,m,F,g,b){const i=p("PaiMark");return n(),d("div",null,[t[0]||(t[0]=a("h1",{id:"pai-文档格式",tabindex:"-1"},[h(".pai 文档格式 "),a("a",{class:"header-anchor",href:"#pai-文档格式","aria-label":'Permalink to ".pai 文档格式"'},"​")],-1)),o(i),t[1]||(t[1]=r('<p>PAI 文档把文字、布局、原图和文档标识放在一起。人可以直接编辑呈现效果，AI 工具可以读取结构化内容并定位具体内容块。</p><h2 id="选择文件形式" tabindex="-1">选择文件形式 <a class="header-anchor" href="#选择文件形式" aria-label="Permalink to &quot;选择文件形式&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th><code>.pai</code></th><th><code>.pai.html</code></th></tr></thead><tbody><tr><td>包含什么</td><td>ZIP 封装中的文档数据和原始图片</td><td>同一份文档和图片，加上渲染及编辑程序</td></tr><tr><td>用什么打开</td><td>兼容的应用或服务</td><td>支持的网页浏览器</td></tr><tr><td>主要用途</td><td>保存、上传、下载和处理文档</td><td>独立分享，在本地离线阅读和编辑</td></tr><tr><td>编辑器来自哪里</td><td>由应用提供</td><td>随导出文件携带</td></tr></tbody></table><p>两种文件使用同一个内容模型。单纯转换封装会保留文档 ID、修订号、文字、布局和全部原始图片。</p><p><img src="'+e+`" alt="同一个文档可以保存为 .pai，或导出为独立的 .pai.html。"></p><h2 id="文档里保存什么" tabindex="-1">文档里保存什么 <a class="header-anchor" href="#文档里保存什么" aria-label="Permalink to &quot;文档里保存什么&quot;">​</a></h2><p>文字使用带稳定 ID 的 Markdown 内容块。布局行规定阅读顺序，以及单栏、双栏或三栏的排列。内容块通过图片 ID 引用资源，同一张原图可以在多个位置按不同尺寸显示。</p><p><code>.pai</code> 内部保存 <code>document.json</code> 和图片文件。<code>.pai.html</code> 把文档 JSON、图片字节和渲染编辑程序一起嵌入文件。工具可以直接提取数据，无需执行其中的网页程序。</p><p>在线服务可以把文档放在自己的数据库和图片存储中，在下载时生成文件。</p><p><a href="/pai-website/spec/format.html">阅读文件规范（英文）</a> · <a href="/pai-website/spec/hash.html">阅读内容哈希规范（英文）</a></p><h2 id="编辑和保存" tabindex="-1">编辑和保存 <a class="header-anchor" href="#编辑和保存" aria-label="Permalink to &quot;编辑和保存&quot;">​</a></h2><p>参考编辑器支持直接改字、Markdown 类语法输入、替换和缩放图片、移动内容块、分栏及背景设置。</p><p>通过 <strong>新建 → 打开现有文件</strong> 导入两种文件。<strong>保存 → 保存 .pai</strong> 下载内容文件。<strong>保存 → 导出独立 HTML</strong> 下载可独立编辑的网页文件。</p><p>从已发布页面保存时，也会下载到本地。修改后的文档通过发布客户端上传，形成更新。</p><h2 id="使用文件工具" tabindex="-1">使用文件工具 <a class="header-anchor" href="#使用文件工具" aria-label="Permalink to &quot;使用文件工具&quot;">​</a></h2><p><a href="/pai-website/zh/getting-started.html">安装项目</a>后，在仓库根目录运行：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> content/cli.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inspect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> content/dist/event.pai</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> content/cli.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> convert</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> content/dist/event.pai</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> event.pai.html</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> content/cli.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> event.pai.html</span></span></code></pre></div><p><code>inspect</code> 返回文档信息和内容，省去图片编码与编辑器代码。其他命令支持局部修改文档，以及按图片 ID 提取原图。</p><p><a href="/pai-website/guide/file-tools.html">文件工具与编辑器指南（英文）</a></p><p>当前文档模型版本为 <code>0.6</code>，ZIP 封装版本为 <code>1</code>。正式文件规范以英文维护。</p>`,20))])}const u=s(l,[["render",c]]);export{C as __pageData,u as default};
